#define BK7258_SYS_CLKSEL             0x44010020u
#define BK7258_SYS_CLK_ENABLE         0x44010030u
#define BK7258_SYS_PWM0_CLKSEL        (1u << 18)
#define BK7258_SYS_PWM0_CLK_ENABLE    (1u << 3)

