#define BK7258_PWM_EDTR               (BK7258_PWM0_BASE + 0x24u)
#define BK7258_PWM_CCMR               (BK7258_PWM0_BASE + 0x28u)
#define BK7258_PWM_PRESCALER          (BK7258_PWM0_BASE + 0x38u)
